using XLConvert
using DataFrames

using Dates

function if_multiple(dividend, divisor, value)
xl_compare(xl_mod(dividend, divisor), 0) ? value : 0.0
end

function calculate_s_Carbon_Sequestration_J26(tab_Carbon_Sequestration_C30_C48, Pump_Capital_Cost, Pipeline_Process_Control_System, CO2_Surge_Tank_C82, tab_HyARC_Physical_Property_Data_A94_B119, Reference_year, tab_HyARC_Physical_Property_Data_D94_E118, tab_HyARC_Physical_Property_Data_G94_H118, CO2_Mass_Flowrate_G_metric_tons_per_year, tab_Carbon_Sequestration_J22_J25)
	# =IF(CO2_PipeDia>20,1.25, IF(CO2_PipeDia>16,1.18,IF(CO2_PipeDia>12,1.12,1)))
	Adjustment_factor_Natural_Gas_Pipeline__>_CO2_Pipeline = (xl_gt(Pipeline_Nominal_Diameter_in, 20.0) ? 1.25 : (xl_gt(Pipeline_Nominal_Diameter_in, 16.0) ? 1.18 : (xl_gt(Pipeline_Nominal_Diameter_in, 12.0) ? 1.12 : 1.0))) # Carbon Sequestration C53
	@assert xl_compare(Adjustment_factor_Natural_Gas_Pipeline__>_CO2_Pipeline, missing) # "Carbon Sequestration!C53"
	# =94000*VLOOKUP(ref_year,Tbl_labor_indexes,2)/VLOOKUP(2008,Tbl_labor_indexes,2)
	Regional_Evaluation_C93 = xl_div(xl_mul(94000.0, xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)), xl_vlookup(2008.0, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)) # Carbon Sequestration C93
	@assert xl_compare(Regional_Evaluation_C93, 109497.94871794869) # "Carbon Sequestration!C93"
	# =(-16600*CO2_flowrate_GTpY^2+53500*CO2_flowrate_GTpY+20300)*1000*VLOOKUP(ref_year,Tbl_labor_indexes,2)/VLOOKUP(2008,Tbl_labor_indexes,2)
	Site_Characterization_C94 = xl_div(xl_mul(((-1 * 16600.0) * ((CO2_Mass_Flowrate_G_metric_tons_per_year) ^ (2.0)) + 53500.0 * CO2_Mass_Flowrate_G_metric_tons_per_year + 20300.0) * 1000.0, xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)), xl_vlookup(2008.0, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)) # Carbon Sequestration C94
	@assert xl_compare(Site_Characterization_C94, 2.364689743589743e7) # "Carbon Sequestration!C94"
	# = (-400*CO2_flowrate_GTpY^2 + 2200*CO2_flowrate_GTpY + 13800)*1000*VLOOKUP(ref_year,Tbl_labor_indexes,2)/VLOOKUP(2008,Tbl_labor_indexes,2)
	Permitting_C95 = xl_div(xl_mul(((-1 * 400.0) * ((CO2_Mass_Flowrate_G_metric_tons_per_year) ^ (2.0)) + 2200.0 * CO2_Mass_Flowrate_G_metric_tons_per_year + 13800.0) * 1000.0, xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)), xl_vlookup(2008.0, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)) # Carbon Sequestration C95
	@assert xl_compare(Permitting_C95, 1.6075230769230762e7) # "Carbon Sequestration!C95"
	# =(185000+CO2_PipeLength*(343*CO2_PipeDia^2+2074*CO2_PipeDia+170013))*NG_to_CO2Pipeline*VLOOKUP(ref_year,Tbl_labor_indexes,2)/VLOOKUP(2000,Tbl_labor_indexes,2)
	Labor = xl_div(xl_mul(xl_mul(xl_add(185000.0, xl_mul(Pipeline_length_miles, xl_add(xl_add(343.0 * ((Pipeline_Nominal_Diameter_in) ^ (2.0)), xl_mul(2074.0, Pipeline_Nominal_Diameter_in)), 170013.0))), Adjustment_factor_Natural_Gas_Pipeline__>_CO2_Pipeline), xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)), xl_vlookup(2000.0, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0)) # Carbon Sequestration C55
	@assert xl_compare(Labor, missing) # "Carbon Sequestration!C55"
	# =(40000+CO2_PipeLength*(0*CO2_PipeDia^2+577*CO2_PipeDia+29788))*NG_to_CO2Pipeline*(VLOOKUP(ref_year,DeflatorTable,2)/VLOOKUP(2000,DeflatorTable,2))
	Right_of_Way_and_Damages = xl_mul(xl_mul(xl_add(40000.0, xl_mul(Pipeline_length_miles, xl_add(xl_add(0.0 * ((Pipeline_Nominal_Diameter_in) ^ (2.0)), xl_mul(577.0, Pipeline_Nominal_Diameter_in)), 29788.0))), Adjustment_factor_Natural_Gas_Pipeline__>_CO2_Pipeline), xl_div(xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_A94_B119[!, Between("A", "B")], 2.0), xl_vlookup(2000.0, tab_HyARC_Physical_Property_Data_A94_B119[!, Between("A", "B")], 2.0))) # Carbon Sequestration C56
	@assert xl_compare(Right_of_Way_and_Damages, missing) # "Carbon Sequestration!C56"
	# =(35000+CO2_PipeLength*(330.5*CO2_PipeDia^2+687*CO2_PipeDia+26960))*NG_to_CO2Pipeline*VLOOKUP(ref_year,Tbl_PlantCostIndexes,2)/VLOOKUP(2000,Tbl_PlantCostIndexes,2)
	Material_Capital = xl_div(xl_mul(xl_mul(xl_add(35000.0, xl_mul(Pipeline_length_miles, xl_add(xl_add(330.5 * ((Pipeline_Nominal_Diameter_in) ^ (2.0)), xl_mul(687.0, Pipeline_Nominal_Diameter_in)), 26960.0))), Adjustment_factor_Natural_Gas_Pipeline__>_CO2_Pipeline), xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0)), xl_vlookup(2000.0, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0)) # Carbon Sequestration C54
	@assert xl_compare(Material_Capital, missing) # "Carbon Sequestration!C54"
	# =(95000+CO2_PipeLength*(0*CO2_PipeDia^2+8417*CO2_PipeDia+7324))*NG_to_CO2Pipeline*VLOOKUP(ref_year,DeflatorTable,2)/VLOOKUP(2000,DeflatorTable,2)
	Miscellaneous_Surveying_engineering_supervision_etc = xl_div(xl_mul(xl_mul(xl_add(95000.0, xl_mul(Pipeline_length_miles, xl_add(xl_add(0.0 * ((Pipeline_Nominal_Diameter_in) ^ (2.0)), xl_mul(8417.0, Pipeline_Nominal_Diameter_in)), 7324.0))), Adjustment_factor_Natural_Gas_Pipeline__>_CO2_Pipeline), xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_A94_B119[!, Between("A", "B")], 2.0)), xl_vlookup(2000.0, tab_HyARC_Physical_Property_Data_A94_B119[!, Between("A", "B")], 2.0)) # Carbon Sequestration C57
	@assert xl_compare(Miscellaneous_Surveying_engineering_supervision_etc, missing) # "Carbon Sequestration!C57"
	tab_Carbon_Sequestration_J22_J25[3, "J"] = xl_sum([CO2_Surge_Tank_C82, Pipeline_Process_Control_System]) # Carbon Sequestration J24 Row: 3
	tab_Carbon_Sequestration_J22_J25[4, "J"] = xl_sum([Regional_Evaluation_C93, Site_Characterization_C94, Permitting_C95]) # Carbon Sequestration J25 Row: 4
	tab_Carbon_Sequestration_J22_J25[2, "J"] = Pump_Capital_Cost # Carbon Sequestration J23 Row: 2
	tab_Carbon_Sequestration_J22_J25[1, "J"] = xl_sum([Material_Capital, Labor, Right_of_Way_and_Damages, Miscellaneous_Surveying_engineering_supervision_etc]) # Carbon Sequestration J22 Row: 1
	# =IF(CO2_Capture_Efficiency,SUM(J22:J25),0)
	s_Carbon_Sequestration_J26 = (xl_logical(Carbon_Capture_Efficiency_pcnt) ? xl_sum(tab_Carbon_Sequestration_J22_J25[!, "J"]) : 0.0) # Carbon Sequestration J26
	@assert xl_compare(s_Carbon_Sequestration_J26, 0) # "Carbon Sequestration!J26"
	
	s_Carbon_Sequestration_J26
end
function calculate_s_Cash_Flow_Analysis_J134(s_Cash_Flow_Analysis_J131, tab_Constants_and_Conversions_A29_B31, Assumed_start_up_year, AEO_2017_Reference_Case, s_Input_Sheet_Template_B59, GJ_C18, kWh_C12)
	tab_Constants_and_Conversions_A29_B31[2, "B"] = 1.0 / kWh_C12 / 1000.0 # Constants and Conversions B30 Row: 2
	tab_Constants_and_Conversions_A29_B31[1, "B"] = GJ_C18 # Constants and Conversions B29 Row: 1
	# =HLOOKUP(startup_year,INDIRECT(TMP_PriceTable),MATCH("Industrial Electricity",INDIRECT(Energy_Feed_List),0),FALSE)*VLOOKUP("kWh",CC_feedconversion,2,FALSE)
	Electricity_Cost__dollar_per_kWh = xl_mul(xl_hlookup(Assumed_start_up_year, exec(toexpr(parse_formula(exec(s_Input_Sheet_Template_B59, ctx))), ctx), xl_match("Industrial Electricity", exec(toexpr(parse_formula(exec(AEO_2017_Reference_Case, ctx))), ctx), 0.0), false), xl_vlookup("kWh", tab_Constants_and_Conversions_A29_B31[!, Between("A", "B")], 2.0, false)) # Carbon Sequestration C25
	@assert xl_compare(Electricity_Cost__dollar_per_kWh, 0.06998061125716411) # "Carbon Sequestration!C25"
	# =IF(J131="",0,CO2_eCost)
	s_Cash_Flow_Analysis_J134 = (xl_eq(s_Cash_Flow_Analysis_J131, "") ? 0.0 : Electricity_Cost__dollar_per_kWh) # Cash Flow Analysis J134
	@assert xl_compare(s_Cash_Flow_Analysis_J134, 0) # "Cash Flow Analysis!J134"
	
	s_Cash_Flow_Analysis_J134
end
function calculate_Pump_Capital_Cost(tab_HyARC_Physical_Property_Data_D94_E118, Reference_year, Pump_Power)
	# =1110*C68*VLOOKUP(ref_year,Tbl_PlantCostIndexes,2)/VLOOKUP(2005,Tbl_PlantCostIndexes,2)
	Pump_Variable_Cost = xl_div(xl_mul(xl_mul(1110.0, Pump_Power), xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0)), xl_vlookup(2005.0, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0)) # Carbon Sequestration C70
	@assert xl_compare(Pump_Variable_Cost, 0) # "Carbon Sequestration!C70"
	# =70000*VLOOKUP(ref_year,Tbl_PlantCostIndexes,2)/VLOOKUP(2005,Tbl_PlantCostIndexes,2)
	Pump_Fixed_Cost_ = xl_div(xl_mul(70000.0, xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0)), xl_vlookup(2005.0, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0)) # Carbon Sequestration C69
	@assert xl_compare(Pump_Fixed_Cost_, 80988.89363519863) # "Carbon Sequestration!C69"
	# =SUM(C69:C70)
	Pump_Capital_Cost = xl_sum([Pump_Fixed_Cost_, Pump_Variable_Cost]) # Carbon Sequestration C71
	@assert xl_compare(Pump_Capital_Cost, 80988.89363519863) # "Carbon Sequestration!C71"
	
	Pump_Capital_Cost
end
function calculate_s_Input_Sheet_Template_E108(Other_non_depreciable_capital_costs, tab_Capital_Costs_C11_C12, Land_required_acres, Cost_of_land__dollar_per_acre, tab_Plant_Scaling_C4_C5, tab_Input_Sheet_Template_E104_E107)
	# =Scale_Factor *1
	s_Input_Sheet_Template_D105 = Scale_Factor * 1.0 # Input_Sheet_Template D105
	@assert xl_compare(s_Input_Sheet_Template_D105, 1.0000009658823863) # "Input_Sheet_Template!D105"
	# =CPIinflator
	s_Input_Sheet_Template_D104 = Consumer_Price_Inflator_2010_to_2016 # Input_Sheet_Template D104
	@assert xl_compare(s_Input_Sheet_Template_D104, 1.100724186648488) # "Input_Sheet_Template!D104"
	# "Input_Sheet_Template!E104":"Input_Sheet_Template!E105"
	@. tab_Input_Sheet_Template_E104_E107[1:2, "E"] = [Cost_of_land__dollar_per_acre, Land_required_acres] * [s_Input_Sheet_Template_D104, s_Input_Sheet_Template_D105]
	# =CPIinflator
	s_Input_Sheet_Template_D107 = Consumer_Price_Inflator_2010_to_2016 # Input_Sheet_Template D107
	@assert xl_compare(s_Input_Sheet_Template_D107, 1.100724186648488) # "Input_Sheet_Template!D107"
	tab_Input_Sheet_Template_E104_E107[3, "E"] = s_Input_Sheet_Template_E104 * s_Input_Sheet_Template_E105 # Input_Sheet_Template E106 Row: 3
	tab_Input_Sheet_Template_E104_E107[4, "E"] = xl_mul(Other_non_depreciable_capital_costs, s_Input_Sheet_Template_D107) # Input_Sheet_Template E107 Row: 4
	# =land_cost+$E$107
	s_Input_Sheet_Template_E108 = s_Input_Sheet_Template_E106 + tab_Input_Sheet_Template_E104_E107[4, "E"] # Input_Sheet_Template E108
	@assert xl_compare(s_Input_Sheet_Template_E108, 2.7518131245464804e6) # "Input_Sheet_Template!E108"
	
	s_Input_Sheet_Template_E108
end
function calculate_s_Cash_Flow_Analysis_J133(Pump_Power, Operating_Capacity_Factor_pcnt, Plant_Output_kg_per_year, tab_Results_D83_G86, tab_Carbon_Sequestration_C21_C22)
	tab_Carbon_Sequestration_C21_C22[1, "C"] = s_Results_D86 # Carbon Sequestration C21 Row: 1
	# =IF(C21=0,0,(pump_power)*cap_factor*24*365/output_kgyear)
	Carbon_Sequestration_Electricity_Usage_kWh_per_kg_H2 = (xl_eq(tab_Carbon_Sequestration_C21_C22[1, "C"], 0.0) ? 0.0 : xl_div(xl_mul(xl_mul(xl_mul(Pump_Power, Operating_Capacity_Factor_pcnt), 24.0), 365.0), Plant_Output_kg_per_year)) # Carbon Sequestration C26
	@assert xl_compare(Carbon_Sequestration_Electricity_Usage_kWh_per_kg_H2, 0.0) # "Carbon Sequestration!C26"
	# = CO2_eUse_kWhpkg
	s_Cash_Flow_Analysis_J133 = Carbon_Sequestration_Electricity_Usage_kWh_per_kg_H2 # Cash Flow Analysis J133
	@assert xl_compare(s_Cash_Flow_Analysis_J133, 0) # "Cash Flow Analysis!J133"
	
	s_Cash_Flow_Analysis_J133
end
function calculate_s_Input_Sheet_Template_E115(Total_plant_staff_number_of_FTEs_employed_by_plant, Burdened_labor_cost_including_overhead__dollar_per_man_hr, tab_HyARC_Physical_Property_Data_G94_H118, Reference_year, Basis_year, tab_Plant_Scaling_C4_C5, tab_Input_Sheet_Template_E113_E114)
	# =Scale_Ratio^0.25
	s_Input_Sheet_Template_D113 = ((Scale_Ratio) ^ (0.25)) # Input_Sheet_Template D113
	@assert xl_compare(s_Input_Sheet_Template_D113, 1.0000003095775865) # "Input_Sheet_Template!D113"
	# =VLOOKUP(ref_year,Tbl_labor_indexes,2,FALSE)/VLOOKUP(BasisYear,Tbl_labor_indexes,2,FALSE)
	s_Input_Sheet_Template_D114 = xl_div(xl_vlookup(Reference_year, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0, false), xl_vlookup(Basis_year, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0, false)) # Input_Sheet_Template D114
	@assert xl_compare(s_Input_Sheet_Template_D114, 1.154804270462633) # "Input_Sheet_Template!D114"
	# "Input_Sheet_Template!E113":"Input_Sheet_Template!E114"
	@. tab_Input_Sheet_Template_E113_E114[!, "E"] = [Total_plant_staff_number_of_FTEs_employed_by_plant, Burdened_labor_cost_including_overhead__dollar_per_man_hr] * [s_Input_Sheet_Template_D113, s_Input_Sheet_Template_D114]
	# =FTEs*2080*FTE_cost
	s_Input_Sheet_Template_E115 = s_Input_Sheet_Template_E113 * 2080.0 * s_Input_Sheet_Template_E114 # Input_Sheet_Template E115
	@assert xl_compare(s_Input_Sheet_Template_E115, 6.485382790646676e6) # "Input_Sheet_Template!E115"
	
	s_Input_Sheet_Template_E115
end
function group_calculate_Cash_Flow_Analysis_S116(tab_Cash_Flow_Analysis_K65_AA113, Target_after_tax_nominal_IRR, tab_Cash_Flow_Analysis_F114_AC116)
	for i in 0:8
		tab_Cash_Flow_Analysis_F114_AC116[3, 6 + i] = xl_add(tab_Cash_Flow_Analysis_K65_AA113[1, 1 + i], xl_npv(Target_after_tax_nominal_IRR, tab_Cash_Flow_Analysis_K65_AA113[2:49, 1:1 + i]))
	end
	
end
function group_calculate_Cash_Flow_Analysis_S115(After_Tax_Nominal_IRR_B27, tab_Cash_Flow_Analysis_K65_AA113, tab_Cash_Flow_Analysis_F114_AC116)
	for i in 0:8
		tab_Cash_Flow_Analysis_F114_AC116[2, 6 + i] = xl_npv(After_Tax_Nominal_IRR_B27, tab_Cash_Flow_Analysis_K65_AA113[1:49, 1:1 + i])
	end
	
end
function group_calculate_Cash_Flow_Analysis_O108(tab_Cash_Flow_Analysis_A65_C113, Start_up_Time_years, tab_Cash_Flow_Analysis_A139_N182, Plant_Output_kg_per_year, tab_Cash_Flow_Analysis_D65_F113, pcnt_of_Variable_Operating_Costs_During_Start_up_pcnt, tab_Cash_Flow_Analysis_K65_AA113)
	for i in 0:43
		tab_Cash_Flow_Analysis_K65_AA113[1 + i, 5] = (xl_eq(tab_Cash_Flow_Analysis_A65_C113[1 + i, 3], "") ? "" : (xl_lt(tab_Cash_Flow_Analysis_A65_C113[1 + i, 3], 0.0) ? 0.0 : (all([xl_eq(tab_Cash_Flow_Analysis_A65_C113[1 + i, 3], 1.0), xl_lt(Start_up_Time_years, 1.0)]) ? (-1 * xl_add(xl_mul(xl_mul(xl_mul(xl_mul(xl_sum(tab_Cash_Flow_Analysis_A139_N182[1:1 + i, 2:5]), Plant_Output_kg_per_year), tab_Cash_Flow_Analysis_D65_F113[1 + i, 2]), pcnt_of_Variable_Operating_Costs_During_Start_up_pcnt), Start_up_Time_years), xl_mul(xl_mul(xl_mul(xl_sum(tab_Cash_Flow_Analysis_A139_N182[1:1 + i, 2:5]), Plant_Output_kg_per_year), tab_Cash_Flow_Analysis_D65_F113[1 + i, 2]), 1.0 - Start_up_Time_years))) : (xl_leq(tab_Cash_Flow_Analysis_A65_C113[1 + i, 3], Start_up_Time_years) ? xl_mul(xl_mul(xl_mul((-1 * xl_sum(tab_Cash_Flow_Analysis_A139_N182[1:1 + i, 2:5])), Plant_Output_kg_per_year), tab_Cash_Flow_Analysis_D65_F113[1 + i, 2]), pcnt_of_Variable_Operating_Costs_During_Start_up_pcnt) : xl_mul(xl_mul((-1 * xl_sum(tab_Cash_Flow_Analysis_A139_N182[1:1 + i, 2:5])), Plant_Output_kg_per_year), tab_Cash_Flow_Analysis_D65_F113[1 + i, 2])))))
	end
	
end
function group_calculate_Cash_Flow_Analysis_O113(tab_Cash_Flow_Analysis_A65_C113, Start_up_Time_years, s_Cash_Flow_Analysis_B278, s_Cash_Flow_Analysis_C278, s_Cash_Flow_Analysis_D278, s_Cash_Flow_Analysis_E278, Plant_Output_kg_per_year, tab_Cash_Flow_Analysis_D65_F113, pcnt_of_Variable_Operating_Costs_During_Start_up_pcnt, Lookup_Electricity_Prices_in_Startup_Year, s_Cash_Flow_Analysis_C279, s_Cash_Flow_Analysis_D279, s_Cash_Flow_Analysis_E279, Feed_B280, LHV, Price_Table_Start_Year_Column_relative, Raw_Price__dollar_per_GJ, tab_Cash_Flow_Analysis_K65_AA113)
