# Level 14
# Used in 1 places: [TableStatement(lhs = tab_Carbon_Sequestration_J36_J40[2, "J"])]
# =5000*CO2_PipeLength*(VLOOKUP(ref_year,Tbl_PlantCostIndexes,2)/VLOOKUP(1999,Tbl_PlantCostIndexes,2))
Pipeline_cost_of__dollar5000_per_mi_yr = xl_mul(5000.0 * Pipeline_length_miles, xl_div(xl_vlookup(inputs.Reference_year, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0), xl_vlookup(1999.0, tab_HyARC_Physical_Property_Data_D94_E118[!, Between("D", "E")], 2.0))) # Carbon Sequestration C61
@assert xl_compare(Pipeline_cost_of__dollar5000_per_mi_yr, 693420.3789042499) # "Carbon Sequestration!C61"
# Used in 1 places: [TableStatement(lhs = tab_Carbon_Sequestration_J36_J40[3, "J"])]
# =C71*CO2_MaintFactor
Total_Other_Equipment_Cost___O_and_M_Factor_C78 = Pump_Capital_Cost * Operation_and_maintenance_factor_for_equipment_pumps_etc # Carbon Sequestration C78
@assert xl_compare(Total_Other_Equipment_Cost___O_and_M_Factor_C78, 3239.5557454079453) # "Carbon Sequestration!C78"
# Used in 1 places: [TableStatement(lhs = tab_Carbon_Sequestration_J36_J40[4, "J"])]
# =SUM(C82:C83)*CO2_MaintFactor
Total_Other_Equipment_Cost___O_and_M_Factor_C86 = xl_sum([CO2_Surge_Tank_C82, Pipeline_Process_Control_System]) * Operation_and_maintenance_factor_for_equipment_pumps_etc # Carbon Sequestration C86
@assert xl_compare(Total_Other_Equipment_Cost___O_and_M_Factor_C86, 0) # "Carbon Sequestration!C86"
# Used in 1 places: [StandardStatement(lhs = Total_ongoing_capital_expenses)]
# =(-36000*CO2_flowrate_GTpY^2+224000*CO2_flowrate_GTpY+47000)*1000*(VLOOKUP(ref_year,Tbl_labor_indexes,2)/VLOOKUP(2008,Tbl_labor_indexes,2))/plant_life
Operations = xl_div(xl_mul(((-1 * 36000.0) * ((CO2_Mass_Flowrate_G_metric_tons_per_year) ^ (2.0)) + 224000.0 * CO2_Mass_Flowrate_G_metric_tons_per_year + 47000.0) * 1000.0, xl_div(xl_vlookup(inputs.Reference_year, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0), xl_vlookup(2008.0, tab_HyARC_Physical_Property_Data_G94_H118[!, Between("G", "H")], 2.0))), Plant_life_years) # Carbon Sequestration C98
@assert xl_compare(Operations, 1.3687243589743585e6) # "Carbon Sequestration!C98"
# Used in 1 places: [StandardStatement(lhs = Total_ongoing_capital_expenses)]
